WITH chosen AS (SELECT customer_id, event_id, label FROM (SELECT customer_id AS customer_id, event_id AS event_id, label AS label, tick AS tick_ord, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY customer_id ASC NULLS FIRST, tick DESC NULLS LAST, event_id DESC NULLS LAST) AS rn__rank FROM events WHERE (customer_id >= ?)) t0__ WHERE rn__rank = 1 ORDER BY customer_id ASC NULLS FIRST, tick_ord DESC NULLS LAST, event_id DESC NULLS LAST) SELECT customer_id, event_id, (COALESCE(CAST(label AS TEXT), '') || COALESCE(CAST(? AS TEXT), '') || ' literal $1') AS name FROM chosen WHERE (customer_id <= ?) ORDER BY customer_id ASC NULLS FIRST;
